process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import fs from 'fs';
import { execSync } from 'child_process';
import { chromium } from 'playwright';
const B='https://dev.avesa.lt';
const U=process.env.WP_USER,P=(process.env.WP_APP_PASS||'').replace(/\s+/g,'');
const AUTH='Basic '+Buffer.from(U+':'+P).toString('base64');
const TOK=process.env.GH_TOKEN||'';
fs.mkdirSync('screenshots',{recursive:true});
const out={marker:'NAV DEPLOY v1',ts:new Date().toISOString()};
async function wp(p,o={}){try{const r=await fetch(B+p,{...o,headers:{'Authorization':AUTH,'Content-Type':'application/json',...(o.headers||{})}});return{status:r.status,text:await r.text()}}catch(e){return{status:0,text:String(e)}}}
function js(t){const i=Math.min(...['[','{'].map(c=>{const x=t.indexOf(c);return x<0?1e9:x}));try{return JSON.parse(t.slice(i))}catch(e){return null}}
const s1=await wp('/wp-json/code-snippets/v1/snippets',{method:'POST',body:JSON.stringify({name:'TEMP Nav Deploy v1',code:Buffer.from('','base64').toString('utf8'),scope:'global',active:true,priority:5})});
out.snip1=js(s1.text)?.id||null;
const s2=await wp('/wp-json/code-snippets/v1/snippets',{method:'POST',body:JSON.stringify({name:'TEMP Nav Autologin v1',code:Buffer.from('','base64').toString('utf8'),scope:'global',active:true,priority:5})});
out.snip2=js(s2.text)?.id||null;
await new Promise(r=>setTimeout(r,3500));

const failai=[['petshop-rinkiniai.php',''],['petshop-katalogas.php','']];
out.deploy={};
for(const [vardas,turinys] of failai){
  fs.writeFileSync('/tmp/pl.txt','turinys='+encodeURIComponent(turinys));
  try{
    const res=execSync(`curl -sk -X POST "${B}/?ps_deploy=Dp77Kk3&apply=1&failas=${vardas}" --data @/tmp/pl.txt --max-time 180`,{encoding:'utf8',maxBuffer:40*1024*1024});
    out.deploy[vardas]=js(res)||res.slice(0,800);
  }catch(e){ out.deploy[vardas]='ERR '+String(e).slice(0,200); }
}

const files=[];
try{
  const br=await chromium.launch();
  const ctx=await br.newContext({ignoreHTTPSErrors:true,viewport:{width:1600,height:1100}});
  const pg=await ctx.newPage();
  const errs=[]; pg.on('pageerror',e=>errs.push(String(e).slice(0,150)));
  const tikr=async(to,zyme)=>{
    await pg.goto(`${B}/?ps_auto=Qz7Rk88&u=${encodeURIComponent(U)}&to=${encodeURIComponent(to)}`,{waitUntil:'domcontentloaded',timeout:60000});
    await pg.waitForTimeout(3500);
    const i=await pg.evaluate(()=>({
      title:document.title,
      juosta:[...document.querySelectorAll('.pskat-nav a')].map(a=>a.textContent.trim()+(a.className.includes('on')?' [AKTYVUS]':'')),
      logo:(document.querySelector('.pskat-logo')||{}).textContent||'',
      paieska:!!document.querySelector('.pskat-search input'),
      eiles:[...document.querySelectorAll('.psr-eile')].map(e=>e.textContent.replace(/\s+/g,' ').trim()),
      eil:document.querySelectorAll('.psr-lentele tbody tr').length,
      tipai:[...document.querySelectorAll('.psr-lentele tbody tr td:nth-child(3)')].map(t=>t.textContent.replace(/\s+/g,' ').trim().slice(0,26)).slice(0,4),
      kaina_tipas:(document.getElementById('psr-kaina')||{}).type||'',
      fatal:/Fatal error|Parse error/i.test(document.body.innerText)?document.body.innerText.slice(0,300):''
    }));
    const f=`screenshots/nav_${zyme}.png`; await pg.screenshot({path:f,fullPage:false}); files.push(f);
    return i;
  };
  out.rinkiniai=await tikr('admin.php?page=ps-rinkiniai','rinkiniai');
  out.forma=await tikr('admin.php?page=ps-rinkiniai&veiksmas=naujas','forma');
  out.katalogas=await tikr('admin.php?page=ps-katalogas','katalogas');
  out.js=errs;
  await br.close();
}catch(e){ out.err=String(e).slice(0,400); }
for(const id of [out.snip1,out.snip2]){ if(id) await wp('/wp-json/code-snippets/v1/snippets/'+id,{method:'POST',body:JSON.stringify({active:false})}); }
async function put(p,buf,m){const r=await fetch('https://api.github.com/repos/raimis079-creator/petshop-bridge/contents/'+p,{method:'PUT',headers:{'Authorization':'Bearer '+TOK,'Content-Type':'application/json','User-Agent':'b'},body:JSON.stringify({message:m,content:buf.toString('base64')})});return r.status}
for(const f of files){ console.log(f,await put(f,fs.readFileSync(f),'nav shot')); }
console.log('info',await put('screenshots/nav_deploy.json',Buffer.from(JSON.stringify(out,null,1)),'rinkrec result nav'));
